/* ===================== 장소별 사건 (place-events.js) =====================
   섬·마을마다 그곳만의 사건을 더한다. 게임 진행 코드는 건드리지 않고, 기존 연결 지점만 감싼다.
   - events : 그 장소에 살거나 배로 들렀을 때 나오는 사건 (기존 PLACE_EVENTS에 더해짐, 기본 13세 이상)
   - kid    : 그 장소에서 자라는 6~12세 어린 시절 사건 (kidPlacePool에 더해짐)
   - first  : 그 장소에 배로 처음 도착했을 때 딱 한 번 나오는 첫인상 장면 (arrive를 감쌈)

   ── 그림 붙이는 법 ──
   1) 사건 키 이름으로 그림을 만든다. 예: pe_p33_a.webp, pk_p33.webp, pf_p33.webp
      (키와 장면 설명 목록은 place-events-images.md 참고)
   2) 그림 파일을 assets/events/ 폴더에 올린다.
   3) 아래 EVENT_IMAGES 목록에 파일 이름을 적는다. 목록에 적힌 그림만 불러오고, 없으면 기존 기본 그림이 나온다.
   ========================================================================== */
